sysevent_script_action.script:
(function executeAction(current, event) {
    var importSetSysId =
        String(event.parm1 || '').trim();

    if (!importSetSysId) {
        gs.error(
            '[ServerDemoIntegrationService] ' +
            'Event parm1 does not contain an import-set sys_id'
        );
        return;
    }

    try {
        var service =
            new ServerDemoIntegrationService();

        var result =
            service.processImportSet(importSetSysId);

        gs.info(
            '[ServerDemoIntegrationService] ' +
            'Transform result=' +
            JSON.stringify(result)
        );
    } catch (exception) {
        gs.error(
            '[ServerDemoIntegrationService] ' +
            'Transform failed. ImportSet=' +
            importSetSysId +
            ', Error=' +
            (exception.message || exception)
        );
    }
})(current, event);
